-- ################
-- ### MONITORS ###
-- ################

-- See https://wiki.hyprland.org/Configuring/Monitors/
hl.monitor({ 
    output = "eDP-1",
    mode = "1920x1080@144",
    position = "0x0", 
    scale = 1
})
hl.monitor({ 
    output = "HDMI-A-1",
    mode = "1920x1080@180",
    position = "1920x0",
    scale = 1
})

