-- #####################
-- ### LOOK AND FEEL ###
-- #####################

-- Refer to https://wiki.hyprland.org/Configuring/Variables/

-- https://wiki.hyprland.org/Configuring/Variables/#general
hl.config({
    general = {
        gaps_in = 4,
        gaps_out = 13,
    
        border_size = 2, 

        -- https://wiki.hyprland.org/Configuring/Variables/#variable-types for info about colors
        col = {
            active_border = { colors = {"rgba(585b70ee)", "rgba(f5c2e7ee)"}, angle = 90 },
            inactive_border = "rgba(1e1e2eee)",
        },
 
        -- Set to true enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,
    
        -- Please see https://wiki.hyprland.org/Configuring/Tearing/ before you turn this on
        allow_tearing = false,
    
        layout = "master",
        -- dwindle = i3 like?
        -- master = dwm like (includes a stack)
    },

    -- https://wiki.hyprland.org/Configuring/Variables/#decoration

    decoration = {
        rounding = 0,
        rounding_power = 0,
    
        -- Change transparency of focused and unfocused windows
        active_opacity = 1.0,
        inactive_opacity = 1.0,
    
        shadow = {
            enabled = true,
            range = 0,
            render_power = 1,
            offset = {5, 5},
            color = "rgba(313244aa)",
            color_inactive = "rgba(11111bbb)",
        },
    
        -- https://wiki.hyprland.org/Configuring/Variables/#blur

        blur = {
            enabled = true,
            size = 4,
            passes = 1, 

            vibrancy = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
    
    ecosystem = {
        no_donation_nag = true,
        no_update_news = true,
    },
})
-- https://wiki.hyprland.org/Configuring/Variables/#animations

-- Default animations, see https://wiki.hyprland.org/Configuring/Animations/ for more

hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1}, {0.32, 1} } })
-- hl.curve("easeOutQuinty", { type = "bezier", points = { {0.23, 1}, {0.32, 1.05} } })
hl.curve("easeOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1} } })
hl.curve("linear", { type = "bezier", points = { {0, 0}, {1, 1} } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5}, {0.75, 1.0} } })
hl.curve("quick", { type = "bezier", points = { {0.15, 0}, {0.1, 1} } })
hl.curve("overshot", { type = "bezier", points = { {0.22, 0.99}, {0.23, 1.03} } })
-- hl.curve("ease", { type = "bezier", points = { {0.25, 0.1}, {0.25, 1.0} } })

hl.animation({ leaf = "global", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "border", enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows", enabled = true, speed = 4.79, bezier = "easeOutQuint" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.2, bezier = "easeOutQuint", style = "popin 89%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.69, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.78, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.53, bezier = "almostLinear" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers", enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 4, bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.5, bezier = "linear", style = "fade" })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.39, bezier = "almostLinear" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4.3, bezier = "overshot", style = "slide" })
hl.animation({ leaf = "specialWorkspaceIn", enabled = true, speed = 4.3, bezier = "overshot", style = "slide bottom" })
hl.animation({ leaf = "specialWorkspaceOut", enabled = true, speed = 4.3, bezier = "overshot", style = "slide top" })


