-- ###################
-- ### KEYBINDINGS ###
-- ###################

-- See https://wiki.hyprland.org/Configuring/Keywords/

-- local mainMod = "SUPER" -- Sets "Windows" key as main modifier
-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more

hl.bind("SUPER" .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind("SUPER" .. " + L", hl.dsp.exec_cmd("hyprlock"))
hl.bind("SUPER" .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind("SUPER" .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind("SUPER" .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER" .. " + R", hl.dsp.exec_cmd(menu))
hl.bind("SUPER" .. " + P", hl.dsp.window.pseudo())
hl.bind("SUPER" .. " + J", hl.dsp.layout("togglesplit")) -- only applies to dwindle. i use master.
hl.bind("SUPER" .. " + F", hl.dsp.exec_cmd(browser))

hl.bind("SUPER" .. " + PRINT", hl.dsp.exec_cmd("hyprshot --freeze -m output --clipboard-only"))
hl.bind("" .. " + PRINT", hl.dsp.exec_cmd("hyprshot --freeze -m region --clipboard-only"))
hl.bind("SUPER" .. " + CTRL + PRINT", hl.dsp.exec_cmd("hyprshot --freeze -m output --output-folder ~/Downloads/"))
hl.bind("" .. " + CTRL + PRINT", hl.dsp.exec_cmd("hyprshot --freeze -m region --output-folder ~/Downloads/"))

hl.bind("ALT" .. " + Q", hl.dsp.window.close())
hl.bind("ALT" .. " + CTRL + Q", hl.dsp.window.kill())
hl.bind("SUPER" .. " + K", hl.dsp.exec_cmd("hyprctl kill"))

hl.bind("SUPER" .. " + F1", hl.dsp.exec_cmd("hyprctl keyword general:layout dwindle"))
hl.bind("SUPER" .. " + F2", hl.dsp.exec_cmd("hyprctl keyword general:layout master"))
hl.bind("SUPER" .. " + SHIFT + F", hl.dsp.window.fullscreen( { mode = "fullscreen", action = "toggle" } ))

-- #### IMPORTANT HYPRSHOT THING #### https://github.com/Gustash/Hyprshot/issues/60
-- old: layerrule = match:namespace selection, no_anim on
hl.layer_rule {
    name = 'no-anim-for-selection',
    match = { namespace = 'selection' },
    no_anim = true,
}
-- old, convert later:
-- removes cursor from screenshot selection box:
-- cursor {
--     no_hardware_cursors = false
--     -- alternatively, use:
--     -- hide_on_key_press = true
-- }

-- Move focus with mainMod + arrow keys

hl.bind("SUPER" .. " + left", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER" .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind("SUPER" .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind("SUPER" .. " + down", hl.dsp.focus({ direction = "down" }))

hl.bind("SUPER" .. " + ALT + left", hl.dsp.window.move({ direction = "left" }))
hl.bind("SUPER" .. " + ALT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind("SUPER" .. " + ALT + up", hl.dsp.window.move({ direction = "up" }))
hl.bind("SUPER" .. " + ALT + down", hl.dsp.window.move({ direction = "down" }))

hl.bind("SUPER" .. " + Grave", hl.dsp.window.cycle_next({ true }))
hl.bind("SUPER" .. " + SHIFT + Grave", hl.dsp.window.cycle_next({ false }))
hl.bind("SUPER" .. " + ALT + Grave", hl.dsp.window.swap({ direction = "right" })) -- unsure if this works.
hl.bind("SUPER" .. " + ALT + SHIFT + Grave", hl.dsp.window.swap({ direction = "left" })) -- unsure if this works either

hl.bind("SUPER" .. " + CTRL + left", hl.dsp.window.resize({ x = -20, y = 0, relative = true }))
hl.bind("SUPER" .. " + CTRL + right", hl.dsp.window.resize({ x = 20, y = 0, relative = true }))
hl.bind("SUPER" .. " + CTRL + up", hl.dsp.window.resize({ x = 0, y = -20, relative = true }))
hl.bind("SUPER" .. " + CTRL + down", hl.dsp.window.resize({ x = 0, y = 20, relative = true }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind("SUPER" .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind("SUPER" .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind("SUPER" .. " + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind("SUPER" .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind("SUPER" .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER" .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind("SUPER" .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER" .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 2%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 2%-"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 10%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 10%-"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- ##############################
-- ### WINDOWS AND WORKSPACES ###
-- ##############################

-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more
-- See https://wiki.hyprland.org/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrule
-- windowrule = float,class:^(kitty)$,title:^(kitty)$

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    name = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
-- pre 0.53:
-- windowrule = nofocus,class:^$,title:^$,xwayland:1,floating:1,fullscreen:0,pinned:0
-- post 0.53:
hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

hl.window_rule({
    name = "move-hyprland-run",
    match = { class = "hyprland-run" },
    move = "20 monitor_h-120",
    float = true,
})
